-- Client Portal database schema for PostgreSQL 16+ / Supabase.
-- Generated by `python -m app.cli schema-sql` from app/db.py; the app also creates these on first start.
-- Diagram and data dictionary: docs/DATA_MODEL.md

CREATE SCHEMA IF NOT EXISTS portal;

CREATE TABLE portal.activity_events (
	seq BIGSERIAL NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	at TIMESTAMP WITH TIME ZONE NOT NULL, 
	action VARCHAR(60) NOT NULL, 
	actor_user_id VARCHAR(36), 
	actor_email VARCHAR(254), 
	actor_name VARCHAR(120), 
	actor_role VARCHAR(16), 
	target JSONB, 
	details JSONB, 
	ip VARCHAR(64), 
	user_agent VARCHAR(200), 
	content_hash VARCHAR(64) NOT NULL, 
	prev_hash VARCHAR(64), 
	hash VARCHAR(64) NOT NULL, 
	redacted_at TIMESTAMP WITH TIME ZONE, 
	CONSTRAINT pk_activity_events PRIMARY KEY (seq), 
	CONSTRAINT uq_activity_events_id UNIQUE (id)
);

CREATE INDEX ix_activity_events_action ON portal.activity_events (action);
CREATE INDEX ix_activity_events_actor_at ON portal.activity_events (actor_user_id, at);
CREATE INDEX ix_activity_events_actor_user_id ON portal.activity_events (actor_user_id);
CREATE INDEX ix_activity_events_at ON portal.activity_events (at);
COMMENT ON TABLE portal.activity_events IS 'Append-only, hash-chained audit trail. Readable by admins only.';
COMMENT ON COLUMN portal.activity_events.action IS 'e.g. auth.login, property.viewed, admin.user_invited';
COMMENT ON COLUMN portal.activity_events.hash IS 'Chains this row to the previous one (tamper evidence)';

CREATE TABLE portal.crm_agents (
	full_name VARCHAR(120), 
	email VARCHAR(254), 
	phone VARCHAR(40), 
	active BOOLEAN NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_agents PRIMARY KEY (id), 
	CONSTRAINT uq_crm_agents_zoho_id UNIQUE (zoho_id)
);

COMMENT ON TABLE portal.crm_agents IS 'Copy of Zoho CRM users (agents).';
COMMENT ON COLUMN portal.crm_agents.full_name IS 'Zoho: Users.full_name';
COMMENT ON COLUMN portal.crm_agents.email IS 'Zoho: Users.email';
COMMENT ON COLUMN portal.crm_agents.phone IS 'Zoho: Users.mobile / Users.phone';
COMMENT ON COLUMN portal.crm_agents.active IS 'Zoho: Users.status';
COMMENT ON COLUMN portal.crm_agents.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_agents.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_agents.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_agents.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.crm_deal_stages (
	name VARCHAR(80) NOT NULL, 
	sequence INTEGER NOT NULL, 
	is_won BOOLEAN NOT NULL, 
	is_lost BOOLEAN NOT NULL, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_deal_stages PRIMARY KEY (name)
);

COMMENT ON TABLE portal.crm_deal_stages IS 'The Deals Stage picklist, in pipeline order.';
COMMENT ON COLUMN portal.crm_deal_stages.name IS 'Zoho: Deals.Stage picklist value';
COMMENT ON COLUMN portal.crm_deal_stages.sequence IS 'Zoho: pick_list_values.sequence_number';
COMMENT ON COLUMN portal.crm_deal_stages.is_won IS 'Closing stage counted as won';
COMMENT ON COLUMN portal.crm_deal_stages.is_lost IS 'Closing stage counted as lost';

CREATE TABLE portal.crm_properties (
	name VARCHAR(200) NOT NULL, 
	address VARCHAR(255), 
	city VARCHAR(120), 
	price NUMERIC(14, 2), 
	property_type VARCHAR(60), 
	listing_type VARCHAR(20), 
	bedrooms INTEGER, 
	bathrooms NUMERIC(4, 1), 
	floor_area INTEGER, 
	status VARCHAR(40), 
	description TEXT, 
	photo_url VARCHAR(500), 
	featured BOOLEAN NOT NULL, 
	listed_date DATE, 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_properties PRIMARY KEY (id), 
	CONSTRAINT uq_crm_properties_zoho_id UNIQUE (zoho_id)
);

CREATE INDEX ix_crm_properties_city ON portal.crm_properties (city);
CREATE INDEX ix_crm_properties_search ON portal.crm_properties (status, listing_type, city, price);
CREATE INDEX ix_crm_properties_status ON portal.crm_properties (status);
COMMENT ON TABLE portal.crm_properties IS 'Copy of the Zoho Properties module (listings).';
COMMENT ON COLUMN portal.crm_properties.name IS 'Zoho: Properties.Name';
COMMENT ON COLUMN portal.crm_properties.address IS 'Zoho: Properties.Address';
COMMENT ON COLUMN portal.crm_properties.city IS 'Zoho: Properties.City';
COMMENT ON COLUMN portal.crm_properties.price IS 'Zoho: Properties.Price. monthly rent for rentals';
COMMENT ON COLUMN portal.crm_properties.property_type IS 'Zoho: Properties.Property_Type';
COMMENT ON COLUMN portal.crm_properties.listing_type IS 'Zoho: Properties.Listing_Type. Sale or Rent';
COMMENT ON COLUMN portal.crm_properties.bedrooms IS 'Zoho: Properties.Bedrooms';
COMMENT ON COLUMN portal.crm_properties.bathrooms IS 'Zoho: Properties.Bathrooms';
COMMENT ON COLUMN portal.crm_properties.floor_area IS 'Zoho: Properties.Floor_Area. sq ft';
COMMENT ON COLUMN portal.crm_properties.status IS 'Zoho: Properties.Status. only Available is shown to clients';
COMMENT ON COLUMN portal.crm_properties.description IS 'Zoho: Properties.Description';
COMMENT ON COLUMN portal.crm_properties.photo_url IS 'Zoho: Properties.Photo_URL';
COMMENT ON COLUMN portal.crm_properties.featured IS 'Zoho: Properties.Featured';
COMMENT ON COLUMN portal.crm_properties.listed_date IS 'Zoho: Properties.Listed_Date';
COMMENT ON COLUMN portal.crm_properties.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_properties.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_properties.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_properties.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.sync_state (
	module VARCHAR(40) NOT NULL, 
	last_modified_at TIMESTAMP WITH TIME ZONE, 
	last_run_at TIMESTAMP WITH TIME ZONE, 
	last_status VARCHAR(20), 
	last_error TEXT, 
	records_synced INTEGER NOT NULL, 
	CONSTRAINT pk_sync_state PRIMARY KEY (module)
);

COMMENT ON TABLE portal.sync_state IS 'Zoho -> portal sync progress per module.';
COMMENT ON COLUMN portal.sync_state.module IS 'Zoho module, e.g. Deals';
COMMENT ON COLUMN portal.sync_state.last_modified_at IS 'Newest Modified_Time copied (incremental cursor)';
COMMENT ON COLUMN portal.sync_state.last_status IS 'ok | error';

CREATE TABLE portal.users (
	id VARCHAR(36) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	name VARCHAR(120), 
	phone VARCHAR(40), 
	zoho_contact_id VARCHAR(40), 
	zoho_lead_id VARCHAR(40), 
	must_change_password BOOLEAN NOT NULL, 
	session_version INTEGER NOT NULL, 
	email_verified_at TIMESTAMP WITH TIME ZONE, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	converted_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(36), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_users PRIMARY KEY (id), 
	CONSTRAINT ck_users_role CHECK (role IN ('admin', 'client', 'guest')), 
	CONSTRAINT ck_users_status CHECK (status IN ('active', 'disabled', 'erased')), 
	CONSTRAINT ck_users_client_contact CHECK (role <> 'client' OR zoho_contact_id IS NOT NULL OR status = 'erased'), 
	CONSTRAINT uq_users_zoho_contact_id UNIQUE (zoho_contact_id), 
	CONSTRAINT fk_users_created_by FOREIGN KEY(created_by) REFERENCES portal.users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ix_users_email ON portal.users (email);
CREATE INDEX ix_users_role ON portal.users (role);
COMMENT ON TABLE portal.users IS 'Portal logins: admins, clients (linked to a Zoho Contact with an active deal) and guests (a Zoho Lead).';
COMMENT ON COLUMN portal.users.email IS 'Sign-in email (lower case)';
COMMENT ON COLUMN portal.users.password_hash IS 'scrypt hash; never the password';
COMMENT ON COLUMN portal.users.role IS 'admin | client | guest';
COMMENT ON COLUMN portal.users.status IS 'active | disabled | erased';
COMMENT ON COLUMN portal.users.zoho_contact_id IS 'Clients: their Zoho Contact (crm_contacts.zoho_id)';
COMMENT ON COLUMN portal.users.zoho_lead_id IS 'Guests: the Zoho Lead created at sign-up (crm_leads.zoho_id)';
COMMENT ON COLUMN portal.users.session_version IS 'Bumped to sign the user out everywhere';

CREATE TABLE portal.consents (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	kind VARCHAR(40) NOT NULL, 
	policy_version VARCHAR(40) NOT NULL, 
	granted_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	withdrawn_at TIMESTAMP WITH TIME ZONE, 
	ip VARCHAR(64), 
	user_agent VARCHAR(200), 
	CONSTRAINT pk_consents PRIMARY KEY (id), 
	CONSTRAINT fk_consents_user_id FOREIGN KEY(user_id) REFERENCES portal.users (id) ON DELETE CASCADE
);

CREATE INDEX ix_consents_user_id ON portal.consents (user_id);
COMMENT ON TABLE portal.consents IS 'What each person agreed to, when, and under which privacy policy version.';
COMMENT ON COLUMN portal.consents.kind IS 'privacy_policy | contact_about_properties';

CREATE TABLE portal.crm_contacts (
	first_name VARCHAR(80), 
	last_name VARCHAR(80) NOT NULL, 
	full_name VARCHAR(160), 
	email VARCHAR(254), 
	phone VARCHAR(40), 
	mobile VARCHAR(40), 
	owner_zoho_id VARCHAR(40), 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_contacts PRIMARY KEY (id), 
	CONSTRAINT fk_crm_contacts_owner_zoho_id FOREIGN KEY(owner_zoho_id) REFERENCES portal.crm_agents (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT uq_crm_contacts_zoho_id UNIQUE (zoho_id)
);

CREATE INDEX ix_crm_contacts_email ON portal.crm_contacts (email);
CREATE INDEX ix_crm_contacts_owner_zoho_id ON portal.crm_contacts (owner_zoho_id);
COMMENT ON TABLE portal.crm_contacts IS 'Copy of Zoho Contacts (clients).';
COMMENT ON COLUMN portal.crm_contacts.first_name IS 'Zoho: Contacts.First_Name';
COMMENT ON COLUMN portal.crm_contacts.last_name IS 'Zoho: Contacts.Last_Name';
COMMENT ON COLUMN portal.crm_contacts.full_name IS 'Zoho: Contacts.Full_Name';
COMMENT ON COLUMN portal.crm_contacts.email IS 'Zoho: Contacts.Email. matches the portal login';
COMMENT ON COLUMN portal.crm_contacts.phone IS 'Zoho: Contacts.Phone';
COMMENT ON COLUMN portal.crm_contacts.mobile IS 'Zoho: Contacts.Mobile';
COMMENT ON COLUMN portal.crm_contacts.owner_zoho_id IS 'Zoho: Contacts.Owner. the client''s agent';
COMMENT ON COLUMN portal.crm_contacts.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_contacts.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_contacts.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_contacts.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.otp_challenges (
	id VARCHAR(36) NOT NULL, 
	purpose VARCHAR(20) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	user_id VARCHAR(36), 
	code_hash VARCHAR(128) NOT NULL, 
	payload JSONB, 
	attempts INTEGER NOT NULL, 
	resends INTEGER NOT NULL, 
	last_sent_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	consumed_at TIMESTAMP WITH TIME ZONE, 
	ip VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_otp_challenges PRIMARY KEY (id), 
	CONSTRAINT ck_otp_challenges_purpose CHECK (purpose IN ('login', 'signup', 'password_reset')), 
	CONSTRAINT fk_otp_challenges_user_id FOREIGN KEY(user_id) REFERENCES portal.users (id) ON DELETE CASCADE
);

CREATE INDEX ix_otp_challenges_email ON portal.otp_challenges (email);
CREATE INDEX ix_otp_challenges_expires_at ON portal.otp_challenges (expires_at);
COMMENT ON TABLE portal.otp_challenges IS 'One-time codes for sign-in, sign-up and password reset (hashes only; deleted after a day).';
COMMENT ON COLUMN portal.otp_challenges.purpose IS 'login | signup | password_reset';
COMMENT ON COLUMN portal.otp_challenges.code_hash IS 'HMAC of the code; the code itself is never stored';

CREATE TABLE portal.crm_deals (
	deal_name VARCHAR(200) NOT NULL, 
	stage VARCHAR(80), 
	amount NUMERIC(14, 2), 
	closing_date DATE, 
	type VARCHAR(60), 
	description TEXT, 
	contact_zoho_id VARCHAR(40), 
	property_zoho_id VARCHAR(40), 
	owner_zoho_id VARCHAR(40), 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_deals PRIMARY KEY (id), 
	CONSTRAINT fk_crm_deals_stage FOREIGN KEY(stage) REFERENCES portal.crm_deal_stages (name) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_deals_contact_zoho_id FOREIGN KEY(contact_zoho_id) REFERENCES portal.crm_contacts (zoho_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_deals_property_zoho_id FOREIGN KEY(property_zoho_id) REFERENCES portal.crm_properties (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_deals_owner_zoho_id FOREIGN KEY(owner_zoho_id) REFERENCES portal.crm_agents (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT uq_crm_deals_zoho_id UNIQUE (zoho_id)
);

CREATE INDEX ix_crm_deals_contact_zoho_id ON portal.crm_deals (contact_zoho_id);
CREATE INDEX ix_crm_deals_property_zoho_id ON portal.crm_deals (property_zoho_id);
COMMENT ON TABLE portal.crm_deals IS 'Copy of Zoho Deals.';
COMMENT ON COLUMN portal.crm_deals.deal_name IS 'Zoho: Deals.Deal_Name';
COMMENT ON COLUMN portal.crm_deals.stage IS 'Zoho: Deals.Stage';
COMMENT ON COLUMN portal.crm_deals.amount IS 'Zoho: Deals.Amount';
COMMENT ON COLUMN portal.crm_deals.closing_date IS 'Zoho: Deals.Closing_Date';
COMMENT ON COLUMN portal.crm_deals.type IS 'Zoho: Deals.Type';
COMMENT ON COLUMN portal.crm_deals.description IS 'Zoho: Deals.Description. shown to the client as the latest update';
COMMENT ON COLUMN portal.crm_deals.contact_zoho_id IS 'Zoho: Deals.Contact_Name. the client; clients only see their own deals';
COMMENT ON COLUMN portal.crm_deals.property_zoho_id IS 'Zoho: Deals.Property';
COMMENT ON COLUMN portal.crm_deals.owner_zoho_id IS 'Zoho: Deals.Owner. agent for this deal';
COMMENT ON COLUMN portal.crm_deals.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_deals.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_deals.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_deals.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.crm_leads (
	kind VARCHAR(20) NOT NULL, 
	first_name VARCHAR(80), 
	last_name VARCHAR(80) NOT NULL, 
	email VARCHAR(254), 
	phone VARCHAR(40), 
	lead_source VARCHAR(60), 
	lead_status VARCHAR(60), 
	inquiry_type VARCHAR(60), 
	match_criteria TEXT, 
	description TEXT, 
	referred_by_zoho_id VARCHAR(40), 
	owner_zoho_id VARCHAR(40), 
	portal_user_id VARCHAR(36), 
	created_time TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_leads PRIMARY KEY (id), 
	CONSTRAINT ck_crm_leads_kind CHECK (kind IN ('signup', 'referral', 'other')), 
	CONSTRAINT fk_crm_leads_referred_by_zoho_id FOREIGN KEY(referred_by_zoho_id) REFERENCES portal.crm_contacts (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_leads_owner_zoho_id FOREIGN KEY(owner_zoho_id) REFERENCES portal.crm_agents (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_leads_portal_user_id FOREIGN KEY(portal_user_id) REFERENCES portal.users (id) ON DELETE SET NULL, 
	CONSTRAINT uq_crm_leads_zoho_id UNIQUE (zoho_id)
);

CREATE INDEX ix_crm_leads_email ON portal.crm_leads (email);
CREATE INDEX ix_crm_leads_portal_user_id ON portal.crm_leads (portal_user_id);
CREATE INDEX ix_crm_leads_referred_by_zoho_id ON portal.crm_leads (referred_by_zoho_id);
COMMENT ON TABLE portal.crm_leads IS 'Copy of Zoho Leads from portal sign-ups and referrals.';
COMMENT ON COLUMN portal.crm_leads.kind IS 'signup | referral | other (from Lead_Source)';
COMMENT ON COLUMN portal.crm_leads.first_name IS 'Zoho: Leads.First_Name';
COMMENT ON COLUMN portal.crm_leads.last_name IS 'Zoho: Leads.Last_Name';
COMMENT ON COLUMN portal.crm_leads.email IS 'Zoho: Leads.Email';
COMMENT ON COLUMN portal.crm_leads.phone IS 'Zoho: Leads.Phone';
COMMENT ON COLUMN portal.crm_leads.lead_source IS 'Zoho: Leads.Lead_Source';
COMMENT ON COLUMN portal.crm_leads.lead_status IS 'Zoho: Leads.Lead_Status';
COMMENT ON COLUMN portal.crm_leads.inquiry_type IS 'Zoho: Leads.Inquiry_Type. referrals';
COMMENT ON COLUMN portal.crm_leads.match_criteria IS 'Zoho: Leads.Portal_Match_Criteria. guests'' latest search';
COMMENT ON COLUMN portal.crm_leads.description IS 'Zoho: Leads.Description';
COMMENT ON COLUMN portal.crm_leads.referred_by_zoho_id IS 'Zoho: Leads.Referred_By. referring client';
COMMENT ON COLUMN portal.crm_leads.owner_zoho_id IS 'Zoho: Leads.Owner';
COMMENT ON COLUMN portal.crm_leads.portal_user_id IS 'Guest account created by this sign-up';
COMMENT ON COLUMN portal.crm_leads.created_time IS 'Zoho: Leads.Created_Time';
COMMENT ON COLUMN portal.crm_leads.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_leads.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_leads.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_leads.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.crm_messages (
	contact_zoho_id VARCHAR(40) NOT NULL, 
	deal_zoho_id VARCHAR(40), 
	property_zoho_id VARCHAR(40), 
	direction VARCHAR(10) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	body TEXT, 
	author_name VARCHAR(120), 
	created_time TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_messages PRIMARY KEY (id), 
	CONSTRAINT ck_crm_messages_direction CHECK (direction IN ('client', 'agent')), 
	CONSTRAINT fk_crm_messages_contact_zoho_id FOREIGN KEY(contact_zoho_id) REFERENCES portal.crm_contacts (zoho_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_messages_deal_zoho_id FOREIGN KEY(deal_zoho_id) REFERENCES portal.crm_deals (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_messages_property_zoho_id FOREIGN KEY(property_zoho_id) REFERENCES portal.crm_properties (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT uq_crm_messages_zoho_id UNIQUE (zoho_id)
);

CREATE INDEX ix_crm_messages_contact_zoho_id ON portal.crm_messages (contact_zoho_id);
COMMENT ON TABLE portal.crm_messages IS 'Copy of portal conversation Notes (never internal agent notes).';
COMMENT ON COLUMN portal.crm_messages.contact_zoho_id IS 'Zoho: Notes.Parent_Id (Contact)';
COMMENT ON COLUMN portal.crm_messages.deal_zoho_id IS 'Deal the message is about (from the note text)';
COMMENT ON COLUMN portal.crm_messages.property_zoho_id IS 'Property the message is about';
COMMENT ON COLUMN portal.crm_messages.direction IS 'client ("[Client Portal]" note) | agent ("[Portal Reply]" note)';
COMMENT ON COLUMN portal.crm_messages.subject IS 'Zoho: Notes.Note_Title. without the prefix';
COMMENT ON COLUMN portal.crm_messages.body IS 'Zoho: Notes.Note_Content';
COMMENT ON COLUMN portal.crm_messages.author_name IS 'Zoho: Notes.Owner. agent replies';
COMMENT ON COLUMN portal.crm_messages.created_time IS 'Zoho: Notes.Created_Time';
COMMENT ON COLUMN portal.crm_messages.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_messages.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_messages.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_messages.synced_at IS 'When the portal last refreshed this row';

CREATE TABLE portal.crm_tasks (
	message_zoho_id VARCHAR(40), 
	subject VARCHAR(255) NOT NULL, 
	status VARCHAR(40), 
	priority VARCHAR(20), 
	due_date DATE, 
	owner_zoho_id VARCHAR(40), 
	contact_zoho_id VARCHAR(40), 
	deal_zoho_id VARCHAR(40), 
	id VARCHAR(36) NOT NULL, 
	zoho_id VARCHAR(40) NOT NULL, 
	zoho_modified_at TIMESTAMP WITH TIME ZONE, 
	synced_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_crm_tasks PRIMARY KEY (id), 
	CONSTRAINT fk_crm_tasks_message_zoho_id FOREIGN KEY(message_zoho_id) REFERENCES portal.crm_messages (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_tasks_owner_zoho_id FOREIGN KEY(owner_zoho_id) REFERENCES portal.crm_agents (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_tasks_contact_zoho_id FOREIGN KEY(contact_zoho_id) REFERENCES portal.crm_contacts (zoho_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT fk_crm_tasks_deal_zoho_id FOREIGN KEY(deal_zoho_id) REFERENCES portal.crm_deals (zoho_id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, 
	CONSTRAINT uq_crm_tasks_zoho_id UNIQUE (zoho_id)
);

COMMENT ON TABLE portal.crm_tasks IS 'Copy of follow-up Tasks created for agents.';
COMMENT ON COLUMN portal.crm_tasks.message_zoho_id IS 'The message that created it';
COMMENT ON COLUMN portal.crm_tasks.subject IS 'Zoho: Tasks.Subject';
COMMENT ON COLUMN portal.crm_tasks.status IS 'Zoho: Tasks.Status';
COMMENT ON COLUMN portal.crm_tasks.priority IS 'Zoho: Tasks.Priority';
COMMENT ON COLUMN portal.crm_tasks.due_date IS 'Zoho: Tasks.Due_Date';
COMMENT ON COLUMN portal.crm_tasks.owner_zoho_id IS 'Zoho: Tasks.Owner';
COMMENT ON COLUMN portal.crm_tasks.contact_zoho_id IS 'Zoho: Tasks.Who_Id';
COMMENT ON COLUMN portal.crm_tasks.deal_zoho_id IS 'Zoho: Tasks.What_Id';
COMMENT ON COLUMN portal.crm_tasks.id IS 'Portal surrogate key';
COMMENT ON COLUMN portal.crm_tasks.zoho_id IS 'Zoho record id (natural key, used for sync and links)';
COMMENT ON COLUMN portal.crm_tasks.zoho_modified_at IS 'Zoho: Modified_Time. drives incremental sync';
COMMENT ON COLUMN portal.crm_tasks.synced_at IS 'When the portal last refreshed this row';

-- ---------------------------------------------------------------------------
-- Supabase lockdown: the portal talks to PostgreSQL directly and does not use
-- Supabase's Data API, Auth or Storage. Keep these tables unreachable from it.
-- (Also switch the Data API off, or leave `portal` out of its exposed schemas.)
-- ---------------------------------------------------------------------------
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON SCHEMA portal FROM anon, authenticated;
    REVOKE ALL ON ALL TABLES IN SCHEMA portal FROM anon, authenticated;
  END IF;
END $$;
-- Row Level Security on with no policies: any role other than the table owner sees nothing.
ALTER TABLE portal.activity_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_deal_stages ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.sync_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.consents ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.otp_challenges ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_deals ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE portal.crm_tasks ENABLE ROW LEVEL SECURITY;

